    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    ink = next(v for v in counts if v != bg)
    out = [row[:] for row in grid]

    # Lines with many aligned marks are the underlying long strokes.
    major_rows = {
        r for r in range(h)
        if sum(grid[r][c] == ink for c in range(w)) >= 10
    }
    major_cols = {
        c for c in range(w)
        if sum(grid[r][c] == ink for r in range(h)) >= 7
    }

    keep = set()
    for r in major_rows:
        cs = [c for c in range(w) if grid[r][c] == ink]
        for c in range(min(cs), max(cs) + 1):
            out[r][c] = ink
            keep.add((r, c))
    for c in major_cols:
        rs = [r for r in range(h) if grid[r][c] == ink]
        for r in range(min(rs), max(rs) + 1):
            out[r][c] = ink
            keep.add((r, c))

    # Keep short unbroken strokes too.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != ink:
                c += 1
                continue
            e = c
            while e + 1 < w and grid[r][e + 1] == ink:
                e += 1
            if e - c + 1 >= 3:
                keep.update((r, x) for x in range(c, e + 1))
            c = e + 1
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != ink:
                r += 1
                continue
            e = r
            while e + 1 < h and grid[e + 1][c] == ink:
                e += 1
            if e - r + 1 >= 3:
                keep.update((x, c) for x in range(r, e + 1))
            r = e + 1

    # Retain cells touching a preserved stroke; erase diagonal-only noise.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != ink or (r, c) in keep:
                continue
            diagonal = any(
                0 <= r + dr < h and 0 <= c + dc < w
                and grid[r + dr][c + dc] == ink
                for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1))
            )
            orthogonal = any(
